        {
          "at": "00:02",
          "text": "'Caminandes'라는 제목이 하늘에 뜬다."
        },
        {
          "at": "00:07",
          "text": "라마가 눈 덮인 들판을 걷는다."
        }
      ],
      "lines_2": [
        {
          "at": "00:10",
          "text": "라마가 작은 꽃을 향해 몸을 숙인다."
        },
        {
          "at": "00:16",
          "text": "라마가 눈 위에 쓰러져 누운다."
        }
      ],
      "lines_3": [
        {
          "at": "00:08",
          "text": "배경에 눈 덮인 산맥이 보인다."
        }
      ]
    },
    {
      "from": "00:20",
      "to": "00:40",
      "lines_1": [
        {
          "at": "00:22",
          "text": "펭귄이 라마 옆에 나타난다."
        },
        {
          "at": "00:33",
          "text": "기차가 눈 덮인 선로를 따라 달려온다."
        }
      ],
      "lines_2": [
        {
          "at": "00:24",
          "text": "펭귄이 잎사귀를 씹으며 라마를 본다."
        },
        {
          "at": "00:35",
          "text": "라마가 기차를 보고 놀란 표정을 짓는다."
        }
      ],
      "lines_3": [
        {
          "at": "00:34",
          "text": "기차에서 하얀 증기가 피어오른다."
        }
      ]
    },
    {
      "from": "00:40",
      "to": "01:00",
      "lines_1": [
        {
          "at": "00:44",
          "text": "기차가 라마와 펭귄을 스쳐 지나간다."
        },
        {
          "at": "00:57",
          "text": "두 캐릭터가 어두운 지하 공간에 있다."
        }
      ],
      "lines_2": [
        {
          "at": "00:46",
          "text": "라마가 기차의 증기 속에 앉아 있다."
        },
        {
          "at": "00:51",
          "text": "라마의 혀 끝에서 포도 한 알이 튕겨 나간다."
        }
      ],
      "lines_3": [
        {
          "at": "00:58",
          "text": "지하 공간의 벽이 바위로 이루어져 있다."
        }
      ]
    },
    {
      "from": "01:00",
      "to": "01:20",
      "lines_1": [
        {
          "at": "01:03",
          "text": "두 캐릭터가 미네카트를 타고 지하를 달린다."
        },
        {
          "at": "01:19",
          "text": "미네카트가 터널 밖으로 튀어나온다."
        }
      ],
      "lines_2": [
        {
          "at": "01:01",
          "text": "펭귄이 포도 한 송이를 들고 있다."
        },
        {
          "at": "01:14",
          "text": "라마가 미네카트 위에서 입을 벌리고 있다."
        }
      ],
      "lines_3": [
        {
          "at": "01:08",
          "text": "지하 터널의 선로가 구불구불하게 이어진다."
        }
      ]
    },
    {
      "from": "01:20",
      "to": "01:40",
      "lines_1": [
        {
          "at": "01:21",
          "text": "두 캐릭터가 공중으로 날아간다."
        },
        {
          "at": "01:36",
          "text": "두 캐릭터가 눈 위에 착지한다."
        }
      ],
      "lines_2": [
        {
          "at": "01:23",
          "text": "포도 한 송이가 공중으로 날아간다."
        },
        {
          "at": "01:38",
          "text": "펭귄이 라마의 배 위에 앉아 있다."
        }
      ],
      "lines_3": [
        {
          "at": "01:25",
          "text": "배경에 눈 덮인 산봉우리가 보인다."
        }
      ]
    },
    {
      "from": "01:40",
      "to": "02:00",
      "lines_1": [
        {
          "at": "01:52",
          "text": "두 캐릭터가 절벽 끝에서 바다를 내려다본다."
        },
        {
          "at": "01:59",
          "text": "펭귄이 포도를 들고 라마에게 다가온다."
        }
      ],
      "lines_2": [
        {
          "at": "01:45",
          "text": "라마의 눈 위에 포도가 붙어 있다."
        },
        {
          "at": "01:55",
          "text": "라마가 바위 위에 앉아 하늘을 본다."
        }
      ],
      "lines_3": [
        {
          "at": "01:53",
          "text": "절벽 옆에 돌로 쌓은 등대가 있다."
        }
      ]
    },
    {
      "from": "02:00",
      "to": "02:20",
      "lines_1": [
        {
          "at": "02:02",
          "text": "포도를 든 펭귄 무리가 라마에게 다가온다."
        },
        {
          "at": "02:15",
          "text": "등대의 불빛이 밤하늘을 비춘다."
        }
      ],
      "lines_2": [
        {
          "at": "02:06",
          "text": "라마가 눈 위에 쌓인 포도를 먹는다."
        },
        {
          "at": "02:10",
          "text": "펭귄 무리가 라마와 펭귄을 둘러싼다."
        }
      ],
      "lines_3": [
        {
          "at": "02:16",
          "text": "밤하늘에 은하수가 흐른다."
        }
      ]
    },
    {
      "from": "02:20",
      "to": "02:30",
      "lines_1": [
        {
          "at": "02:20",
          "text": "엔딩 크레딧이 올라간다."
        }
      ],
      "lines_2": [
        {
          "at": "02:29",
          "text": "'Caminandes Llamigos'라는 제목이 뜬다."
        }
      ],
      "lines_3": []
    }
  ],
  "summary_30s": "라마와 펭귄이 눈 덮인 들판에서 만나 기차와 광산 미네카트를 타고 모험을 한다. 두 캐릭터는 공중으로 날아 눈 위에 착지한 뒤, 등대 앞의 펭귄 무리와 함께 포도를 먹으며 밤하늘을 바라본다."
}

